<script setup>
import{computed}from'vue';import{useEducation,responseType,gradingMode}from'@/services/education.js';const props=defineProps({question:{required:true},subject:String});const emit=defineEmits(['change']);const{catalog}=useEducation();const type=computed(()=>responseType(props.question));const mode=computed(()=>gradingMode(props.question));
function choose(value){const q=props.question;q.responseType=value;q.gradingMode=['single_choice','multiple_choice','true_false'].includes(value)?'exact':'manual';if(!['practice','check','replacement'].includes(q.kind))q.kind=value;if(['single_choice','multiple_choice'].includes(value)&&!q.options?.length)q.options=[{id:'A',text:''},{id:'B',text:''}];emit('change')}
function addOption(){const q=props.question;q.options||=[];if(q.options.length<12){q.options.push({id:String.fromCharCode(65+q.options.length),text:''});emit('change')}}
</script>
<template><div class="general-question-editor"><div class="subject-fields"><label class="field-label">题型<AppSelect :model-value="type" :options="catalog.responseTypes" label="题型" @update:model-value="choose"/></label><label class="field-label">核对方式<AppSelect :model-value="mode" :options="catalog.gradingModes" label="核对方式" @update:model-value="question.gradingMode=$event;emit('change')"/></label></div><label class="field-label">题目内容<Textarea v-model="question.prompt" @update:model-value="emit('change')"/></label><div v-if="['single_choice','multiple_choice'].includes(type)" class="question-options-editor"><label v-for="option in question.options||[]" :key="option.id" class="field-label">{{option.id}}<Input v-model="option.text" :aria-label="'选项'+option.id" @update:model-value="emit('change')"/></label><AppButton variant="outline" type="button" @click="addOption">添加选项</AppButton></div><label v-if="subject==='数学'||question.equation||mode==='math'" class="field-label">数学表达式<Textarea v-model="question.equation" @update:model-value="emit('change')"/></label><label class="field-label">{{mode==='manual'?'参考答案与评价要点':'参考答案'}}<Textarea v-model="question.answer" @update:model-value="emit('change')"/></label><label class="field-label">解析<Textarea v-model="question.explanation" @update:model-value="emit('change')"/></label><details class="study-disclosure"><summary>提示与评分依据</summary><label class="field-label">提示<Textarea v-model="question.hint" @update:model-value="emit('change')"/></label><label class="field-label">评分依据<Textarea v-model="question.rubric" @update:model-value="emit('change')"/></label></details></div></template>
